def solve():
    n = int(input())
    a = list(map(int, input().split()))
    s = input()

    graph = defaultdict(list)
    for i in range(n):
        for j in range(i + 1, n):
            if a[i]!= a[j]:
                break
            graph[a[i]].append(a[j])

    que = deque()
    visited = set()
    for i in range(n):
        if a[i] not in visited:
            que.append((a[i], s[i]))
            visited.add(a[i])

    while que:
        num, char = que.popleft()
        for nei in graph[num]:
            if s[a.index(nei)]!= char:
                print("NO")
                return
            if nei not in visited:
                que.append((nei, char))
                visited.add(nei)

    print("YES")

